script:
(function () {
  'use strict';
  // Tip and bill split.
  //   tax   = round2(bill x tax%)
  //   tip   = round2(tip base x tip%), tip base = bill (pre-tax, default) or bill + tax
  //   total = bill + tax + tip; each share = total / people, worked in whole cents so any
  //   leftover cent is shown rather than lost.
  //   Rounding up: "share" rounds each person's share up to the next whole dollar (total = share x
  //   people); "total" rounds the total up to the next dollar. The extra goes to the tip, and the
  //   effective tip rate = tip / tip base.
  // Verified (Node scratch test): $60, 18% -> tip $10.80, total $70.80; $85.50, 8% tax, 20% on the
  // pre-tax bill, 3 people -> tax $6.84, tip $17.10, total $109.44, $36.48 each; same bill rounded
  // up per person -> $37 each, total $111.00, tip $18.66 (21.82%); $100, 0% tip, 3 people -> $33.34
  // for 1 person and $33.33 for 2.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var pct = new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 });
  var COMPARE = [10, 15, 18, 20, 22, 25];

  function num(id) {
    var s = String(document.getElementById(id).value).trim();
    if (s === '') return NaN;
    var v = Number(s);
    return isFinite(v) ? v : NaN;
  }
  function cents(x) { return Math.round(x * 100 + 1e-7 * Math.sign(x)); }
  function set(id, text) { document.getElementById(id).textContent = text; }

  // All money values are returned in whole cents.
  function tipBill(o) {
    var billC = cents(o.bill);
    var taxC = cents(o.bill * o.taxRate / 100);
    var baseC = o.preTax ? billC : billC + taxC;
    var tipC = cents(baseC * o.tipRate / 100 / 100);
    var totalC = billC + taxC + tipC;
    if (o.round === 'share') {
      var perC = Math.ceil(totalC / o.people / 100 - 1e-9) * 100;
      totalC = perC * o.people;
    } else if (o.round === 'total') {
      totalC = Math.ceil(totalC / 100 - 1e-9) * 100;
    }
    tipC = totalC - billC - taxC;
    var shareLow = Math.floor(totalC / o.people);
    var extra = totalC - shareLow * o.people; // people who pay one cent more
    return { bill: billC, tax: taxC, base: baseC, tip: tipC, total: totalC,
             shareLow: shareLow, extra: extra,
             effRate: baseC > 0 ? tipC / baseC * 100 : 0 };
  }

  function update() {
    var o = { bill: num('tpBill'), tipRate: num('tpRate'), people: num('tpPeople'),
              taxRate: num('tpTax'), preTax: document.getElementById('tpPreTax').checked,
              round: document.getElementById('tpRound').value };
    var error = document.getElementById('tpError');
    var bad = [o.bill, o.tipRate, o.people, o.taxRate].some(isNaN) || o.bill < 0 || o.bill > 1e9 ||
              o.tipRate < 0 || o.tipRate > 100 || o.taxRate < 0 || o.taxRate > 30 ||
              o.people < 1 || o.people > 100 || Math.floor(o.people) !== o.people;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a bill of $0 or more, a tip from 0 to 100%, a tax rate from 0 to 30% and 1 to 100 people (whole number).';
      ['tpTip', 'tpTotal', 'tpShare', 'tpShareTip', 'tpRowBill', 'tpRowTax', 'tpRowTip', 'tpRowTotal'].forEach(function (id) { set(id, '–'); });
      set('tpEffRate', '');
      document.getElementById('tpSplitNote').hidden = true;
      document.getElementById('tpCompare').innerHTML = '';
      return;
    }
    var r = tipBill(o);
    set('tpTip', money.format(r.tip / 100));
    set('tpTotal', money.format(r.total / 100));
    var shareHigh = r.shareLow + (r.extra > 0 ? 1 : 0);
    set('tpShare', money.format(shareHigh / 100));
    set('tpShareTip', money.format(r.tip / o.people / 100));
    set('tpRowBill', money.format(r.bill / 100));
    set('tpRowTax', money.format(r.tax / 100));
    set('tpRowTip', money.format(r.tip / 100));
    set('tpRowTotal', money.format(r.total / 100));
    set('tpEffRate', o.round !== 'none' || o.tipRate !== Math.round(r.effRate * 100) / 100
      ? 'Effective tip rate after rounding: ' + pct.format(r.effRate) + '% of ' + money.format(r.base / 100) + '.'
      : 'Tip of ' + pct.format(o.tipRate) + '% on ' + money.format(r.base / 100) + (o.preTax && r.tax > 0 ? ' (the bill before tax).' : '.'));
    var note = document.getElementById('tpSplitNote');
    note.hidden = r.extra === 0;
    if (r.extra > 0) {
      note.textContent = 'The total doesn’t split evenly to the cent: ' + r.extra + (r.extra === 1 ? ' person pays ' : ' people pay ') +
        money.format(shareHigh / 100) + ' and ' + (o.people - r.extra) + (o.people - r.extra === 1 ? ' person pays ' : ' people pay ') +
        money.format(r.shareLow / 100) + '.';
    }
    var rates = COMPARE.indexOf(o.tipRate) === -1 ? COMPARE.concat([o.tipRate]).sort(function (a, b) { return a - b; }) : COMPARE;
    document.getElementById('tpCompare').innerHTML = rates.map(function (rate) {
      var c = tipBill({ bill: o.bill, tipRate: rate, people: o.people, taxRate: o.taxRate, preTax: o.preTax, round: 'none' });
      var share = c.shareLow + (c.extra > 0 ? 1 : 0);
      var mine = rate === o.tipRate ? ' (yours)' : '';
      return '<tr><td>' + pct.format(rate) + '%' + mine + '</td><td>' + money.format(c.tip / 100) + '</td><td>' +
             money.format(c.total / 100) + '</td><td>' + money.format(share / 100) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('tpForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
